import 'dart:developer' as developer;

/// Represents the structured decision output generated by the [DecisionEngine].
class TheftDecision {
  /// The evaluated risk score that triggered this decision (0.0 to 100.0).
  final double riskScore;

  /// Whether the phone screen lock action is triggered (Risk >= 85.0).
  final bool triggerLock;

  /// Whether the user-facing alarm alert or vibration notification is triggered (Risk >= 60.0).
  final bool triggerAlert;

  /// Whether real-time GPS coordinate/location tracking is triggered (Risk >= 45.0).
  final bool triggerLiveTracking;

  /// Whether front camera photo capture is triggered (Risk >= 70.0).
  final bool triggerCamera;

  /// Human-readable recommendation or description of the security action status.
  final String recommendationMessage;

  /// The timestamp of when this decision was generated.
  final DateTime timestamp;

  TheftDecision({
    required this.riskScore,
    required this.triggerLock,
    required this.triggerAlert,
    required this.triggerLiveTracking,
    required this.triggerCamera,
    required this.recommendationMessage,
    required this.timestamp,
  });

  /// Helper getter to identify if any defense actions were triggered.
  bool get hasTriggers => triggerLock || triggerAlert || triggerLiveTracking || triggerCamera;

  @override
  String toString() {
    return 'TheftDecision(Risk: ${riskScore.toStringAsFixed(2)}%, '
        'Lock: $triggerLock, Alert: $triggerAlert, Tracking: $triggerLiveTracking, Camera: $triggerCamera)';
  }
}

/// A service responsible for taking security mitigation decisions based on
/// behavioral biometric risk scores.
/// 
/// ### THRESHOLD DESIGN & EXPLANATION
/// 
/// The decision engine utilizes four distinct security risk thresholds to
/// invoke defensive triggers in a graduated, multi-layered fashion:
/// 
/// 1. **Live Tracking ($T_{\text{tracking}} = 45.0$):**
///    - **Rationale:** At this level, risk has entered the "Warning" to "Suspicious" transition.
///      While not confident enough to lock the screen (which causes user friction), it warrants active
///      GPS monitoring so that if the device is lost or stolen, location trails are logged.
/// 
/// 2. **Alert Trigger ($T_{\text{alert}} = 60.0$):**
///    - **Rationale:** At this level, risk has entered the "Suspicious" zone. We trigger an alert
///      (such as UI overlays, warnings, vibrations, or an audio sound) to warn the user, prompt
///      re-authentication, or deter a casual snooper/pickpocket.
/// 
/// 3. **Camera Capture ($T_{\text{camera}} = 70.0$):**
///    - **Rationale:** High suspicion of unauthorized use. The front-facing camera is triggered to
///      silently capture a snapshot of whoever is holding the screen, aiding in identity verification.
/// 
/// 4. **Phone Lock ($T_{\text{lock}} = 85.0$):**
///    - **Rationale:** Critical risk indicating a severe profile mismatch (e.g. non-owner holds).
///      To protect sensitive information, the device is locked down immediately, requesting primary credentials
///      (PIN/Password) to restore access.
class DecisionEngine {
  // Configurable thresholds for the different defensive actions
  final double thresholdLock;
  final double thresholdAlert;
  final double thresholdTracking;
  final double thresholdCamera;

  /// Default constructor with standard threat mitigation thresholds.
  DecisionEngine({
    this.thresholdLock = 85.0,
    this.thresholdAlert = 60.0,
    this.thresholdTracking = 45.0,
    this.thresholdCamera = 70.0,
  });

  /// Evaluates the current risk score and returns a [TheftDecision].
  /// 
  /// [riskScore] is the security risk score from 0.0 to 100.0.
  TheftDecision evaluateRisk(double riskScore) {
    final DateTime now = DateTime.now();

    // Defensive triggers evaluation
    final bool triggerLock = riskScore >= thresholdLock;
    final bool triggerAlert = riskScore >= thresholdAlert;
    final bool triggerLiveTracking = riskScore >= thresholdTracking;
    final bool triggerCamera = riskScore >= thresholdCamera;

    // Generate appropriate recommendation message
    String recommendation;
    if (triggerLock) {
      recommendation = 'CRITICAL: High threat detected. Lock phone immediately and require PIN/Pattern.';
    } else if (triggerCamera) {
      recommendation = 'SUSPICIOUS: Mismatched profile. Silently capture front-facing camera image.';
    } else if (triggerAlert) {
      recommendation = 'WARNING: Behavior deviation. Flash warning notification and trigger alert.';
    } else if (triggerLiveTracking) {
      recommendation = 'NOTICE: Minor anomaly. Enable live tracking coordinate capturing.';
    } else {
      recommendation = 'SAFE: Normal user behavior verified. No mitigation action needed.';
    }

    final decision = TheftDecision(
      riskScore: riskScore,
      triggerLock: triggerLock,
      triggerAlert: triggerAlert,
      triggerLiveTracking: triggerLiveTracking,
      triggerCamera: triggerCamera,
      recommendationMessage: recommendation,
      timestamp: now,
    );

    developer.log(
      'DecisionEngine: Evaluated risk: ${riskScore.toStringAsFixed(2)}% -> Triggers: '
      '[Lock: $triggerLock, Alert: $triggerAlert, Tracking: $triggerLiveTracking, Camera: $triggerCamera]',
      name: 'DecisionEngine',
    );

    return decision;
  }
}
